  /**
   * Initializes the SDK
   * @param {*} sdkKey
   */
  static initialize(sdkKey) {
    const instance = this.getInstance();
    if (instance.initialized) {
      console.warn('Gleap already initialized.');
      return;
    }

    instance.initialized = true;

    // Start capturing the session replay as early as possible. Capture is
    // otherwise only kicked off once the config round-trip finishes, which
    // leaves a window (slow network, uncached first visit) where a user can
    // open feedback before the recorder is running and submit an empty replay.
    // If this project has web replays disabled, applyConfig() stops the
    // recorder again. That transient buffer can't reach a ticket: the feedback
    // widget (the only thing that emits 'flow-started', which is what snapshots
    // the buffer) is injected after the config has loaded, i.e. after the stop.
    try {
      GleapReplayRecorder.getInstance().startIfNotRunning();
    } catch (error) {}

    try {
      fixGleapHeight();
    } catch (error) {}

    // Start session
    const sessionInstance = GleapSession.getInstance();
    sessionInstance.sdkKey = sdkKey;
    sessionInstance.setOnSessionReady(() => {
      // Run auto configuration.
      setTimeout(() => {
        GleapConfigManager.getInstance()
          .start()
          .then(() => {
            GleapStreamedEvent.getInstance().start();

            runFunctionWhenDomIsReady(() => {
              // Inject the widget buttons
              GleapFeedbackButtonManager.getInstance().injectFeedbackButton();

              // Inject the notification container
              GleapNotificationManager.getInstance().injectNotificationUI();

              // Check for uncompleted tour.
              Gleap.checkForUncompletedTour();

              // Check for URL params.
              Gleap.checkForUrlParams();

              // A capture request that was in progress before this page load.
              try {
                GleapCaptureManager.getInstance().resumeFromStorage();
              } catch (exp) {}

              // Notify event.
              GleapEventManager.notifyEvent('initialized');
            });
          })
          .catch(function (err) {
            console.warn('Failed to initialize Gleap.');
          });
      }, 0);
    });
    sessionInstance.startSession();
  }

