  /**
   * Sends a silent feedback report
   * @param {*} formData
   * @param {*} priority
   * @param {*} excludeData
   */
  static sendSilentCrashReport(
    description = '',
    priority = 'MEDIUM',
    excludeData = {
      screenshot: true,
      replays: true,
      attachments: true,
    }
  ) {
    return Gleap.sendSilentCrashReportWithFormData(
      {
        description,
      },
      priority,
      excludeData
    );
  }

  /**
   * Sends a silent feedback report
   * @param {*} formData
   * @param {*} priority
   * @param {*} excludeData
   */
  static sendSilentCrashReportWithFormData(
    formData,
    priority = 'MEDIUM',
    excludeData = {
      screenshot: true,
      replays: true,
      attachments: true,
    }
  ) {
    if (this.silentCrashReportSent) {
      return;
    }

    this.silentCrashReportSent = true;
    setTimeout(() => {
      this.silentCrashReportSent = false;
    }, 10000);

    const excludeDataCleaned = excludeData ? gleapDataParser(excludeData) : {};
    const sessionInstance = GleapSession.getInstance();
    if (!sessionInstance.ready) {
      return;
    }

    var newFormData = formData ? formData : {};
    if (sessionInstance.session.email) {
      newFormData.reportedBy = sessionInstance.session.email;
    }

    const feedback = new GleapFeedback('CRASH', priority, newFormData, true, excludeDataCleaned);
    feedback
      .sendFeedback()
      .then(() => {})
      .catch((error) => {});
  }

  /**
   * Shows a survey.
   *
   * The second argument is either a legacy format string ('survey', 'survey_full', 'survey_web')
   * or an options object: { format?: 'card' | 'full' | 'page', fields?: Record<string, string>,
   * personalToken?: string, container?: HTMLElement | string, resume?: boolean }.
   * @param {string} surveyId
   * @param {string|object} formatOrOptions
   */
  static showSurvey(surveyId, formatOrOptions = 'survey') {
    // Called before the session is ready (right after initialize): show it once it is.
    const sessionInstance = GleapSession.getInstance();
    if (!sessionInstance.ready) {
      sessionInstance.setOnSessionReady(() => {
        Gleap.showSurvey(surveyId, formatOrOptions);
      });
      return;
    }

    // The messenger reads the contact once, when the survey starts, to skip the contact questions
    // it already knows: wait for an identify / updateContact still in flight (capped).
    sessionInstance.onContactSettled(() => {
      const options = normalizeSurveyOptions(formatOrOptions);
      Gleap.startFeedbackFlowWithOptions(
        surveyId,
        {
          hideBackButton: true,
          format: options.appMode,
          survey: options,
        },
        true
      );
    });
  }

