  /**
   * Performs an action.
   * @param {*} action
   */
  performActions(actions) {
    for (let i = 0; i < actions.length; i++) {
      const action = actions[i];
      if (action && action.actionType) {
        // Notification bubbles get their page rules evaluated at render time
        // (and re-evaluated on URL changes) by GleapNotificationManager. The
        // server marks outbound actions as sent on delivery, so suppressing
        // them here on an excluded page would consume the notification
        // without the user ever seeing it. Banners, modals, surveys, tours
        // and checklists opening the widget stay gated at arrival.
        const pageRulesCheckedAtRenderTime =
          action.actionType === 'notification' && action?.data?.checklist?.popupType !== 'widget';

        if (
          !pageRulesCheckedAtRenderTime &&
          (action.pageRules?.length > 0 || action.pageFilter) &&
          window &&
          window.location
        ) {
          const passed = checkPageRules(window.location.href, action);

          if (!passed) {
            continue;
          }
        }

        if (action.actionType === 'notification') {
          if (action?.data?.checklist?.popupType === 'widget') {
            Gleap.openChecklist(action.data.checklist.id, true);
          } else {
            if (!this.disableInAppNotifications) {
              Gleap.showNotification(action);
            }
          }
        } else if (action.actionType === 'banner') {
          Gleap.showBanner(action);
        } else if (action.actionType === 'modal') {
          Gleap.showModal(action);
        } else if (action.actionType === 'tour') {
          Gleap.startProductTourWithConfig(action.outbound, action.data, false);
        } else {
          // An inline survey page owns the messenger frame: never swap it for a triggered survey.
          if (GleapFrameManager.getInstance().appMode === 'survey_page') {
            continue;
          }
          Gleap.showSurvey(action.actionType, {
            format: action.format,
            resume: action.resume === true,
            resumeData: action.resume === true ? action.data : undefined,
            outboundAction: action._id || action.id,
          });
        }
      }
    }
  }

